def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); mask=8
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0,mask) or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<h and 0<=y<w and grid[x][y] not in (0,mask) and (x,y) not in seen:
                        seen.add((x,y)); stack.append((x,y))
            comps.append(comp)
    templates=Counter()
    for comp in comps:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==mask for r,c in comp for dr in (-1,0,1) for dc in (-1,0,1)): continue
        r0=min(r for r,c in comp); c0=min(c for r,c in comp)
        shape=tuple(sorted((r-r0,c-c0,grid[r][c]) for r,c in comp))
        templates[shape]+=1
    if not templates:
        comp=max(comps,key=len) if comps else []
        if comp:
            r0=min(r for r,c in comp); c0=min(c for r,c in comp)
            templates[tuple(sorted((r-r0,c-c0,grid[r][c]) for r,c in comp))]=1
    out=[[0 if v==mask else v for v in row] for row in grid]
    candidates=[]
    for shape,freq in templates.items():
        sh=max(x for x,y,v in shape)+1; sw=max(y for x,y,v in shape)+1
        cells={(x,y):v for x,y,v in shape}
        for r in range(h-sh+1):
            for c in range(w-sw+1):
                known=[]; missing=[]; valid=True
                for x in range(sh):
                    for y in range(sw):
                        actual=grid[r+x][c+y]; expected=cells.get((x,y),0)
                        if actual!=mask and actual!=expected: valid=False; break
                        if expected:
                            if actual==mask: missing.append((r+x,c+y,expected))
                            else: known.append((r+x,c+y))
                    if not valid: break
                if valid and known and missing:
                    candidates.append((len(known),len(shape),freq,known,missing))
    used=set()
    for _,__,___,known,missing in sorted(candidates,reverse=True):
        if any(p in used for p in known): continue
        for r,c,v in missing: out[r][c]=v
        used.update(known)
    return out

